import React, { useState } from 'react';
import './Usuarios.css';

function Usuarios() {
  const [users, setUsers] = useState([
    { id: 1, name: 'Juan Pérez', email: 'juan@example.com', role: 'usuario' },
    { id: 2, name: 'Ana Gómez', email: 'ana@example.com', role: 'administrador' },
    { id: 3, name: 'Luis Martínez', email: 'luis@example.com', role: 'usuario' },
    { id: 4, name: 'Carlos Rodríguez', email: 'carlos@example.com', role: 'usuario' },
    { id: 5, name: 'Maria López', email: 'maria@example.com', role: 'administrador' },
    // Agrega más usuarios si es necesario
  ]);

  const [searchTerm, setSearchTerm] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [usersPerPage] = useState(3); // Número de usuarios por página
  const [selectedUser, setSelectedUser] = useState(null); // Para el modal

  // Filtrar usuarios según el término de búsqueda
  const filteredUsers = users.filter(user => 
    user.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    user.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // Paginación
  const indexOfLastUser = currentPage * usersPerPage;
  const indexOfFirstUser = indexOfLastUser - usersPerPage;
  const currentUsers = filteredUsers.slice(indexOfFirstUser, indexOfLastUser);

  const paginate = (pageNumber) => setCurrentPage(pageNumber);

  // Manejadores de acciones
  const handleChangeRole = (id, newRole) => {
    setUsers(users.map(user =>
      user.id === id ? { ...user, role: newRole } : user
    ));
  };

  const handleDeleteUser = (id) => {
    setUsers(users.filter(user => user.id !== id));
  };

  const handleViewMore = (user) => {
    setSelectedUser(user);
    document.getElementById('modal').style.display = 'block';
  };

  const handleCloseModal = () => {
    document.getElementById('modal').style.display = 'none';
  };

  return (
    <div>
      <h1>Gestión de Usuarios</h1>

      {/* Búsqueda */}
      <input 
        type="text" 
        placeholder="Buscar por nombre, apellido o email" 
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)} 
      />

      {/* Tabla de usuarios */}
      <table className="user-table">
        <thead>
          <tr>
            <th>Nombre</th>
            <th>Email</th>
            <th>Rol</th>
            <th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {currentUsers.map(user => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.email}</td>
              <td>{user.role}</td>
              <td>
                <button onClick={() => handleViewMore(user)}>Ver Más</button>
                <button onClick={() => handleChangeRole(user.id, user.role === 'usuario' ? 'administrador' : 'usuario')}>
                  Cambiar Rol
                </button>
                <button onClick={() => handleDeleteUser(user.id)}>Dar de Baja</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Paginación */}
      <div className="pagination">
        {Array.from({ length: Math.ceil(filteredUsers.length / usersPerPage) }, (_, index) => (
          <button 
            key={index + 1}
            onClick={() => paginate(index + 1)}
            className={index + 1 === currentPage ? 'active' : ''}
          >
            {index + 1}
          </button>
        ))}
      </div>

      {/* Modal - Ver más información */}
      {selectedUser && (
        <div id="modal" className="modal">
          <div className="modal-content">
            <span className="close" onClick={handleCloseModal}>&times;</span>
            <h2>Información de Usuario</h2>
            <p><strong>Nombre:</strong> {selectedUser.name}</p>
            <p><strong>Email:</strong> {selectedUser.email}</p>
            <p><strong>Rol:</strong> {selectedUser.role}</p>
          </div>
        </div>
      )}
    </div>
  );
}

export default Usuarios;
